CREATE TABLE IF NOT EXISTS image (id BINARY(16) NOT NULL PRIMARY KEY, "path" TEXT NOT NULL, hash VARCHAR(255) NOT NULL, origin TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "user" (id BINARY(16) NOT NULL PRIMARY KEY, username VARCHAR(255) NOT NULL, displayName VARCHAR(255) NULL, passwordHash VARCHAR(255) NOT NULL, isAdmin BOOLEAN DEFAULT 0 NOT NULL, profileImageId BINARY(16) NULL, server TEXT NULL, CONSTRAINT fk_user_profileImageId__id FOREIGN KEY (profileImageId) REFERENCES image(id) ON DELETE SET NULL ON UPDATE RESTRICT);
CREATE UNIQUE INDEX IF NOT EXISTS user_username_server ON "user" (username, server);
CREATE TABLE IF NOT EXISTS genre (id BINARY(16) NOT NULL PRIMARY KEY, "name" VARCHAR(255) NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS genre_name ON genre ("name");
CREATE TABLE IF NOT EXISTS playlist (id BINARY(16) NOT NULL PRIMARY KEY, "name" VARCHAR(255) NOT NULL, imageId BINARY(16) NULL, explicitlySaved BOOLEAN DEFAULT 0 NOT NULL, CONSTRAINT fk_playlist_imageId__id FOREIGN KEY (imageId) REFERENCES image(id) ON DELETE SET NULL ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS userPlaylist (id BINARY(16) NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, description TEXT DEFAULT '' NOT NULL, customIdentifier TEXT NULL, creator BINARY(16) NOT NULL, imageId BINARY(16) NULL, origin TEXT NULL, modifiedAt BIGINT NULL, explicitlySaved BOOLEAN DEFAULT 0 NOT NULL, CONSTRAINT fk_userPlaylist_creator__id FOREIGN KEY (creator) REFERENCES "user"(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_userPlaylist_imageId__id FOREIGN KEY (imageId) REFERENCES image(id) ON DELETE SET NULL ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS recentlyPlayedSong (userId BINARY(16) NOT NULL, songId VARCHAR(36) NOT NULL, "timestamp" BIGINT NOT NULL, payload TEXT NOT NULL, CONSTRAINT pk_recentlyPlayedSong PRIMARY KEY (userId, songId), CONSTRAINT fk_recentlyPlayedSong_userId__id FOREIGN KEY (userId) REFERENCES "user"(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS recentlyPlayedAlbum (userId BINARY(16) NOT NULL, albumId VARCHAR(36) NOT NULL, "timestamp" BIGINT NOT NULL, payload TEXT NOT NULL, CONSTRAINT pk_recentlyPlayedAlbum PRIMARY KEY (userId, albumId), CONSTRAINT fk_recentlyPlayedAlbum_userId__id FOREIGN KEY (userId) REFERENCES "user"(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS recentlyPlayedArtist (userId BINARY(16) NOT NULL, artistId VARCHAR(36) NOT NULL, "timestamp" BIGINT NOT NULL, payload TEXT NOT NULL, CONSTRAINT pk_recentlyPlayedArtist PRIMARY KEY (userId, artistId), CONSTRAINT fk_recentlyPlayedArtist_userId__id FOREIGN KEY (userId) REFERENCES "user"(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS scrobbleQueue (id INTEGER PRIMARY KEY AUTOINCREMENT, userId BINARY(16) NOT NULL, songId VARCHAR(36) NOT NULL, "timestamp" BIGINT NOT NULL, target TEXT NOT NULL, payload TEXT NOT NULL, CONSTRAINT fk_scrobbleQueue_userId__id FOREIGN KEY (userId) REFERENCES "user"(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT chk_scrobbleQueue_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647));
CREATE TABLE IF NOT EXISTS localHistory (id INTEGER PRIMARY KEY AUTOINCREMENT, userId BINARY(16) NOT NULL, songId VARCHAR(36) NOT NULL, "timestamp" BIGINT NOT NULL, payload TEXT NOT NULL, CONSTRAINT fk_localHistory_userId__id FOREIGN KEY (userId) REFERENCES "user"(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT chk_localHistory_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647));
CREATE TABLE IF NOT EXISTS album (id BINARY(16) NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, tags TEXT DEFAULT '[]' NOT NULL, releaseDate VARCHAR(128) NULL, songCount INT DEFAULT 0 NOT NULL, cover BINARY(16) NULL, originalId TEXT NULL, totalDuration BIGINT DEFAULT 0 NOT NULL, totalSize BIGINT DEFAULT 0 NOT NULL, explicitlySaved BOOLEAN DEFAULT 0 NOT NULL, musicBrainzId BINARY(16) NULL, CONSTRAINT fk_album_cover__id FOREIGN KEY (cover) REFERENCES image(id) ON DELETE SET NULL ON UPDATE RESTRICT, CONSTRAINT chk_album_signed_integer_songCount CHECK (songCount BETWEEN -2147483648 AND 2147483647));
CREATE TABLE IF NOT EXISTS artist (id BINARY(16) NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "group" BOOLEAN DEFAULT 0 NOT NULL, groupId BINARY(16) NULL, about TEXT DEFAULT '' NOT NULL, image BINARY(16) NULL, isFollowed BOOLEAN DEFAULT 0 NOT NULL, explicitlySaved BOOLEAN DEFAULT 0 NOT NULL, musicBrainzId BINARY(16) NULL, CONSTRAINT fk_artist_groupId__id FOREIGN KEY (groupId) REFERENCES artist(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_artist_image__id FOREIGN KEY (image) REFERENCES image(id) ON DELETE SET NULL ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS userPlaylistSong (playlistId BINARY(16) NOT NULL, songId BINARY(16) NOT NULL, addedAt BIGINT NOT NULL, musicBrainzId BINARY(16) NULL, CONSTRAINT pk_userPlaylistSong PRIMARY KEY (playlistId, songId, addedAt), CONSTRAINT fk_userPlaylistSong_playlistId__id FOREIGN KEY (playlistId) REFERENCES userPlaylist(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_userPlaylistSong_songId__id FOREIGN KEY (songId) REFERENCES song(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS songGuessGame (id INTEGER PRIMARY KEY AUTOINCREMENT, userId BINARY(16) NOT NULL, playedAt BIGINT NOT NULL, score INT NOT NULL, maxScore INT NOT NULL, rounds INT NOT NULL, config TEXT NOT NULL, roundResults TEXT NOT NULL, CONSTRAINT fk_songGuessGame_userId__id FOREIGN KEY (userId) REFERENCES "user"(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT chk_songGuessGame_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_songGuessGame_signed_integer_score CHECK (score BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_songGuessGame_signed_integer_maxScore CHECK (maxScore BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_songGuessGame_signed_integer_rounds CHECK (rounds BETWEEN -2147483648 AND 2147483647));
CREATE TABLE IF NOT EXISTS songGuessSavedGame (userId BINARY(16) NOT NULL PRIMARY KEY, updatedAt BIGINT NOT NULL, "state" TEXT NOT NULL, CONSTRAINT fk_songGuessSavedGame_userId__id FOREIGN KEY (userId) REFERENCES "user"(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS settings_sync_known ("key" TEXT NOT NULL PRIMARY KEY, "value" TEXT NULL, version BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS "song" (id BINARY(16) NOT NULL PRIMARY KEY, title TEXT DEFAULT '' NOT NULL, tags TEXT DEFAULT '[]' NOT NULL, albumId BINARY(16) NULL, duration BIGINT DEFAULT 0 NOT NULL, releaseDate VARCHAR(128) NULL, explicit BOOLEAN DEFAULT 0 NOT NULL, filePath TEXT DEFAULT '' NOT NULL, cover BINARY(16) NULL, originalUrl TEXT DEFAULT '' NOT NULL, trackNumber INT DEFAULT 1 NOT NULL, discNumber INT DEFAULT 1 NOT NULL, copyright TEXT DEFAULT '' NOT NULL, codec TEXT DEFAULT '' NOT NULL, sampleRate INT DEFAULT 0 NOT NULL, bitsPerSample INT DEFAULT 0 NOT NULL, bitRate BIGINT DEFAULT 0 NOT NULL, fileSize BIGINT DEFAULT 0 NOT NULL, channels INT DEFAULT 0 NOT NULL, audioStartMs BIGINT NULL, inserted BIGINT DEFAULT 0 NOT NULL, favourite BOOLEAN DEFAULT 0 NOT NULL, superLikedAt BIGINT NULL, createdAt BIGINT NULL, updatedAt BIGINT NULL, explicitlySaved BOOLEAN DEFAULT 0 NOT NULL, musicBrainzId BINARY(16) NULL, CONSTRAINT fk_song_albumId__id FOREIGN KEY (albumId) REFERENCES album(id) ON DELETE SET NULL ON UPDATE RESTRICT, CONSTRAINT fk_song_cover__id FOREIGN KEY (cover) REFERENCES image(id) ON DELETE SET NULL ON UPDATE RESTRICT, CONSTRAINT chk_song_signed_integer_trackNumber CHECK (trackNumber BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_song_signed_integer_discNumber CHECK (discNumber BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_song_signed_integer_sampleRate CHECK (sampleRate BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_song_signed_integer_bitsPerSample CHECK (bitsPerSample BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_song_signed_integer_channels CHECK (channels BETWEEN -2147483648 AND 2147483647));
CREATE TABLE IF NOT EXISTS "songArtist" (songId BINARY(16) NOT NULL, artistId BINARY(16) NOT NULL, CONSTRAINT pk_songArtist PRIMARY KEY (songId, artistId), CONSTRAINT fk_songArtist_songId__id FOREIGN KEY (songId) REFERENCES song(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_songArtist_artistId__id FOREIGN KEY (artistId) REFERENCES artist(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS "albumArtist" (albumId BINARY(16) NOT NULL, artistId BINARY(16) NOT NULL, CONSTRAINT pk_albumArtist PRIMARY KEY (albumId, artistId), CONSTRAINT fk_albumArtist_albumId__id FOREIGN KEY (albumId) REFERENCES album(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_albumArtist_artistId__id FOREIGN KEY (artistId) REFERENCES artist(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS "artistMember" (groupId BINARY(16) NOT NULL, memberId BINARY(16) NOT NULL, CONSTRAINT pk_artistMember PRIMARY KEY (groupId, memberId), CONSTRAINT fk_artistMember_groupId__id FOREIGN KEY (groupId) REFERENCES artist(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_artistMember_memberId__id FOREIGN KEY (memberId) REFERENCES artist(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS "playlistSong" (playlistId BINARY(16) NOT NULL, songId BINARY(16) NOT NULL, "position" INT DEFAULT 0 NOT NULL, CONSTRAINT pk_playlistSong PRIMARY KEY (playlistId, songId), CONSTRAINT fk_playlistSong_playlistId__id FOREIGN KEY (playlistId) REFERENCES playlist(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_playlistSong_songId__id FOREIGN KEY (songId) REFERENCES song(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT chk_playlistSong_signed_integer_position CHECK ("position" BETWEEN -2147483648 AND 2147483647));
CREATE TABLE IF NOT EXISTS "song_genre" (songId BINARY(16) NOT NULL, genreId BINARY(16) NOT NULL, CONSTRAINT pk_song_genre PRIMARY KEY (songId, genreId), CONSTRAINT fk_song_genre_songId__id FOREIGN KEY (songId) REFERENCES song(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_song_genre_genreId__id FOREIGN KEY (genreId) REFERENCES genre(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS "album_genre" (albumId BINARY(16) NOT NULL, genreId BINARY(16) NOT NULL, CONSTRAINT pk_album_genre PRIMARY KEY (albumId, genreId), CONSTRAINT fk_album_genre_albumId__id FOREIGN KEY (albumId) REFERENCES album(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_album_genre_genreId__id FOREIGN KEY (genreId) REFERENCES genre(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS "artist_genre" (artistId BINARY(16) NOT NULL, genreId BINARY(16) NOT NULL, CONSTRAINT pk_artist_genre PRIMARY KEY (artistId, genreId), CONSTRAINT fk_artist_genre_artistId__id FOREIGN KEY (artistId) REFERENCES artist(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_artist_genre_genreId__id FOREIGN KEY (genreId) REFERENCES genre(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS song_lyrics (songId BINARY(16) NOT NULL PRIMARY KEY, candidateId BINARY(16) NOT NULL, provider TEXT NOT NULL, providerName TEXT NOT NULL, providerUrl TEXT NULL, providerEnabled BOOLEAN NOT NULL, providerPriority INT NOT NULL, syncLevel VARCHAR(16) NOT NULL, instrumental BOOLEAN NOT NULL, "match" VARCHAR(16) NOT NULL, durationGapSec INT NULL, "rank" INT NOT NULL, preferred BOOLEAN NOT NULL, content BLOB NULL, plain TEXT NOT NULL, fetchedAt BIGINT NOT NULL, CONSTRAINT fk_song_lyrics_songId__id FOREIGN KEY (songId) REFERENCES song(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT chk_song_lyrics_signed_integer_providerPriority CHECK (providerPriority BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_song_lyrics_signed_integer_durationGapSec CHECK (durationGapSec BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_song_lyrics_signed_integer_rank CHECK ("rank" BETWEEN -2147483648 AND 2147483647));
